const incoming = $input.first().json;
const payload = incoming.body ?? incoming;
const rows = Array.isArray(payload.transactions) ? payload.transactions : [];
const paymentLabels = { paid: 'Cash', gcash: 'GCash', pay_later: 'Pay Later' };

const escapeCsv = (value) => {
  if (value === null || value === undefined) return '';
  const text = typeof value === 'object' ? JSON.stringify(value) : String(value);
  return `\"${text.replace(/\"/g, '\"\"')}\"`;
};

const headers = [
  'Transaction ID', 'Date', 'Customer', 'Phone', 'Service', 'Kg', 'Loads',
  'Base Amount', 'Add-ons', 'Add-on Names', 'Add-on Quantity', 'Total',
  'Cash Received', 'GCash Received', 'GCash Reference', 'Payment Method',
  'Pickup Date', 'Pickup Time', 'Notes', 'Created At'
];

const lines = [headers.map(escapeCsv).join(',')];
for (const row of rows) {
  const service = row.services?.code ?? row.services?.label ?? '';
  const addOnItems = Array.isArray(row.add_on_items) ? row.add_on_items : [];
  const addOnNames = addOnItems.map((item) => item.name ?? '').join(', ');
  const addOnQuantities = addOnItems.map((item) => item.quantity ?? '').join(', ');
  const values = [
    row.transaction_code ?? row.transaction_no ?? '',
    row.transaction_date ?? '',
    row.customer_name ?? '',
    row.phone_number ?? '',
    service,
    row.kg ?? '',
    row.no_of_loads ?? '',
    row.base_amount ?? 0,
    row.add_ons ?? 0,
    addOnNames,
    addOnQuantities,
    row.total_amount ?? 0,
    row.cash_amount ?? 0,
    row.gcash_amount ?? 0,
    row.gcash_reference ?? '',
    paymentLabels[row.payment_method] ?? row.payment_method ?? '',
    row.pickup_date ?? '',
    row.pickup_time ?? '',
    row.notes ?? '',
    row.created_at ?? ''
  ];
  lines.push(values.map(escapeCsv).join(','));
}

const filename = `${payload.export_name || 'aquaspin-transactions'}.csv`;
return [{ json: { filename, csv: lines.join('\n'), row_count: rows.length } }];

const trigger = $('Aquaspin Export Webhook').first().json;
const payload = trigger.body ?? trigger;
const rows = Array.isArray(payload.transactions) ? payload.transactions : [];
const paymentLabels = { paid: 'Cash', gcash: 'GCash', pay_later: 'Pay Later' };

return rows.map((row) => {
  const service = row.services?.code ?? row.services?.label ?? '';
  const addOnItems = Array.isArray(row.add_on_items) ? row.add_on_items : [];
  const addOnNames = addOnItems.map((item) => item.name ?? '').join(', ');
  const addOnQuantities = addOnItems.map((item) => item.quantity ?? '').join(', ');
  return {
    json: {
      'Transaction ID': row.transaction_code ?? row.transaction_no ?? '',
      'Date': row.transaction_date ?? '',
      'Customer': row.customer_name ?? '',
      'Phone': row.phone_number ?? '',
      'Service': service,
      'Kg': row.kg ?? '',
      'Loads': row.no_of_loads ?? '',
      'Base Amount': row.base_amount ?? 0,
      'Add-ons': row.add_ons ?? 0,
      'Add-on Names': addOnNames,
      'Add-on Quantity': addOnQuantities,
      'Total': row.total_amount ?? 0,
      'Cash Received': row.cash_amount ?? 0,
      'GCash Received': row.gcash_amount ?? 0,
      'GCash Reference': row.gcash_reference ?? '',
      'Payment Method': paymentLabels[row.payment_method] ?? row.payment_method ?? '',
      'Pickup Date': row.pickup_date ?? '',
      'Pickup Time': row.pickup_time ?? '',
      'Notes': row.notes ?? '',
      'Created At': row.created_at ?? ''
    }
  };
});
